import{_ as t,o as a,c as o,a4 as n}from"./chunks/framework.DCsBdTIw.js";const u=JSON.parse('{"title":"VS Code + Claude Code","description":"Use Claude Code, Cline, or any VS Code extension that supports a custom Base URL to connect to Tokeness.","frontmatter":{"title":"VS Code + Claude Code","description":"Use Claude Code, Cline, or any VS Code extension that supports a custom Base URL to connect to Tokeness."},"headers":[],"relativePath":"integrations/vscode-claude-code.md","filePath":"integrations/vscode-claude-code.md","lastUpdated":1784332800000}'),s={name:"integrations/vscode-claude-code.md"};function i(d,e,l,r,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="vs-code-claude-code" tabindex="-1">VS Code + Claude Code <a class="header-anchor" href="#vs-code-claude-code" aria-label="Permalink to &quot;VS Code + Claude Code&quot;">​</a></h1><p>There are three common ways to use AI coding tools with Tokeness inside VS Code:</p><table tabindex="0"><thead><tr><th>Approach</th><th>Reference</th></tr></thead><tbody><tr><td>Run Claude Code in the VS Code terminal</td><td>See the Claude Code page</td></tr><tr><td>Use the Cline extension</td><td>See the Cline page</td></tr><tr><td>Use another extension that supports a custom Base URL</td><td>Follow the general fields on this page</td></tr></tbody></table><p>Tokeness exposes a general OpenAI-compatible endpoint:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.dev/v1</span></span></code></pre></div><h2 id="_1-run-claude-code-in-the-vs-code-terminal" tabindex="-1">1. Run Claude Code in the VS Code terminal <a class="header-anchor" href="#_1-run-claude-code-in-the-vs-code-terminal" aria-label="Permalink to &quot;1. Run Claude Code in the VS Code terminal&quot;">​</a></h2><p>If you only use VS Code as a terminal, the configuration is the same as for regular Claude Code:</p><ol><li>Install Claude Code.</li><li>Install CC Switch.</li><li>Add the Tokeness provider for Claude Code in CC Switch.</li><li>Enable routing mode.</li><li>Run <code>claude</code> in the VS Code terminal.</li></ol><p>In this scenario, do not re-enter the key in the VS Code extension settings. Claude Code reads its own configuration.</p><p>See: <a href="/integrations/claude-code">Claude Code</a></p><h2 id="_2-use-the-cline-extension" tabindex="-1">2. Use the Cline extension <a class="header-anchor" href="#_2-use-the-cline-extension" aria-label="Permalink to &quot;2. Use the Cline extension&quot;">​</a></h2><p>Cline is a VS Code extension that supports an OpenAI Compatible provider.</p><p>Field values:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Provider: OpenAI Compatible</span></span>
<span class="line"><span>Base URL: https://n.tokeness.dev/v1</span></span>
<span class="line"><span>API Key: your Tokeness API key</span></span>
<span class="line"><span>Model ID: copied from the Tokeness model marketplace</span></span></code></pre></div><p>See: <a href="/integrations/cline">Cline</a></p><h2 id="_3-use-other-vs-code-ai-extensions" tabindex="-1">3. Use other VS Code AI extensions <a class="header-anchor" href="#_3-use-other-vs-code-ai-extensions" aria-label="Permalink to &quot;3. Use other VS Code AI extensions&quot;">​</a></h2><p>As long as an extension exposes these fields, you can try connecting it to Tokeness:</p><table tabindex="0"><thead><tr><th>Extension field</th><th>Tokeness value</th></tr></thead><tbody><tr><td>API Provider</td><td>OpenAI Compatible / OpenAI</td></tr><tr><td>API Key</td><td>Tokeness API key</td></tr><tr><td>Base URL / API Base / Endpoint</td><td><code>https://n.tokeness.dev/v1</code></td></tr><tr><td>Model / Model ID</td><td>Full model name from the Tokeness model marketplace</td></tr></tbody></table><p>If an extension only supports logging in to a specific vendor and does not allow a custom Base URL, it cannot connect to Tokeness directly.</p><h2 id="_4-claude-code-llm-gateway-notes" tabindex="-1">4. Claude Code LLM Gateway notes <a class="header-anchor" href="#_4-claude-code-llm-gateway-notes" aria-label="Permalink to &quot;4. Claude Code LLM Gateway notes&quot;">​</a></h2><p>Claude Code officially supports connecting to an LLM Gateway via <code>ANTHROPIC_BASE_URL</code>, but this requires the gateway to expose the Anthropic Messages format.</p><p>The Claude Code integration in the Tokeness documentation defaults to the CC Switch routing mode, because it can redirect Claude Code requests to an OpenAI-compatible provider. Only when you explicitly use an Anthropic Messages-compatible endpoint should you follow the Anthropic API page.</p><p>Related pages:</p><ul><li><a href="/integrations/claude-code">Claude Code</a></li><li><a href="/integrations/anthropic-api">Anthropic API</a></li></ul><h2 id="_5-keys-and-quota" tabindex="-1">5. Keys and quota <a class="header-anchor" href="#_5-keys-and-quota" aria-label="Permalink to &quot;5. Keys and quota&quot;">​</a></h2><p>VS Code extensions typically read project context, so their consumption is higher than a plain chat session.</p><p>Recommended practices:</p><ul><li>Create a separate key for each VS Code extension.</li><li>Set a quota on the key.</li><li>Start with read-only tasks on first use.</li><li>Confirm the Git working tree status before making large-scale changes.</li><li>Filter usage logs by key to review call records.</li></ul><h2 id="_6-verification" tabindex="-1">6. Verification <a class="header-anchor" href="#_6-verification" aria-label="Permalink to &quot;6. Verification&quot;">​</a></h2><p>In the extension or Claude Code, enter:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Please reply with a single sentence confirming the VS Code integration is working.</span></span></code></pre></div><p>Then check the Tokeness usage logs:</p><ol><li>A new request appears.</li><li>The key is the one dedicated to the VS Code extension.</li><li>The model name is correct.</li><li>The status code is successful.</li></ol><h2 id="_7-troubleshooting" tabindex="-1">7. Troubleshooting <a class="header-anchor" href="#_7-troubleshooting" aria-label="Permalink to &quot;7. Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Extension does not show a Base URL field</td><td>The extension may not support custom APIs</td></tr><tr><td>Authentication failed</td><td>Check the key, whitespace, and whether it is enabled</td></tr><tr><td>404 Not Found</td><td>Set Base URL to <code>https://n.tokeness.dev/v1</code></td></tr><tr><td>model not found</td><td>Re-copy the model name from the model marketplace</td></tr><tr><td>No Claude Code logs</td><td>Check whether CC Switch has Tokeness enabled and routing mode on</td></tr><tr><td>Extension can chat but cannot edit code</td><td>Switch to a model with stronger coding ability, or use Cline / Claude Code</td></tr><tr><td>Abnormal consumption</td><td>Limit the context range and check for looping tasks</td></tr></tbody></table><h2 id="external-docs" tabindex="-1">External docs <a class="header-anchor" href="#external-docs" aria-label="Permalink to &quot;External docs&quot;">​</a></h2><ul><li><a href="https://docs.anthropic.com/en/docs/claude-code/llm-gateway" target="_blank" rel="noreferrer">Claude Code LLM Gateway</a></li><li><a href="https://docs.anthropic.com/zh-CN/docs/claude-code/settings" target="_blank" rel="noreferrer">Claude Code Settings</a></li><li><a href="https://docs.cline.bot/provider-config/openai-compatible" target="_blank" rel="noreferrer">Cline OpenAI Compatible Provider</a></li></ul>`,37)])])}const C=t(s,[["render",i]]);export{u as __pageData,C as default};
